{
  "headline": "FDA's records trace our supply to a plant classified OAI 181 days before the posting",
  "headline_cites": ["E7", "E12"],
  "sentences": [
    {
      "text": "The FDA shortage list shows Par Health, USA LLC discontinued micafungin sodium injection with an initial posting date of 2026-09-11.",
      "cites": ["E12"]
    },
    {
      "text": "Our product label identifies Zydus Lifesciences Limited (FEI 3013712903) as the manufacturing plant.",
      "cites": ["E9"]
    },
    {
      "text": "FDA inspection 1236639 of that plant ended on 2024-04-23 and was classified OAI with 10 observations including absence of written procedures and validation lacking for sterile drug products.",
      "cites": ["E7"]
    },
    {
      "text": "The OAI classification became known on 2024-07-22, which was 181 days before the shortage posting date of 2026-09-11.",
      "cites": ["E7", "E12"]
    },
    {
      "text": "A Warning Letter was issued to Zydus Lifesciences Limited on 2024-08-29 following the OAI inspection.",
      "cites": ["E8"]
    },
    {
      "text": "A Class III recall (D-0596-2024) for micafungin for injection 100 mg/vial manufactured for Northstar Rx LLC was initiated on 2024-07-02 due to cross contamination with other products.",
      "cites": ["E10"]
    },
    {
      "text": "Corvale East has 14 days on hand and Corvale General has 31 days on hand at current usage rates.",
      "cites": ["D1", "D2"]
    }
  ]
}
